def solve():
    import random
    # Try random search first
    for _ in range(100000):
        seq = [random.choice([-1, 1]) for _ in range(22)]
        cost = 0
        for k in range(1, 22):
            ck = sum(seq[i]*seq[i+k] for i in range(22-k))
            cost += ck*ck
            if cost > 56:
                break
        if cost <= 56:
            return seq
    return None

print(solve())
